-- expected 200 collateral pins; a short seed must fail here rather than
-- leave every downstream count quietly wrong.
DO $$
DECLARE n INTEGER;
BEGIN
  SELECT count(*) INTO n FROM collateral;
  IF n <> 200 THEN
    RAISE EXCEPTION 'expected 200 collateral pins, found %', n;
  END IF;
END $$;

